import json
m=json.load(open('data/6/metadata.json'))
ins=m['instruments']
for k in ins:
    p=ins[k]['snapshot']['parameters']
    if k.startswith('k_2400'):
        for pn in ('volt','curr','nplci','nplcv','mode','rangev','compliancei'):
            if pn in p: print(k,pn,'value=',p[pn].get('value'),'step=',p[pn].get('step'),'inter_delay=',p[pn].get('inter_delay'),'post_delay=',p[pn].get('post_delay'))
    if k.startswith('sr'):
        for pn in ('amplitude','frequency','time_constant','sensitivity','filter_slope','X'):
            if pn in p: print(k,pn,'=',p[pn].get('value'))
    if k=='magnet':
        for pn in p: print('magnet',pn,'=',p[pn].get('value'))
" 2>&1 | head -60

